mapper.select:
SELECT * FROM ( SELECT ITEM_NAME, CATEGORY, COUNT(*) AS ITEM_COUNT FROM (
SELECT COALESCE(nc.CODENAME_1, m.MEDICINE_NAME) AS ITEM_NAME, '의약품' AS CATEGORY FROM DOCTOR_PRESCRIPTION dp JOIN MEDICINE m ON dp.MEDICINE_CODE = m.MEDICINE_CODE LEFT JOIN COMMONCODE nc ON nc.COMMONCODE_NUMBER = m.MEDICINE_NAME AND nc.COMMONCODE = 'M' WHERE EXTRACT(YEAR FROM dp.PRESCRIPTION_DATE) = #{year}
UNION ALL
SELECT COALESCE(nc2.CODENAME_1, m2.MEDICINE_NAME) AS ITEM_NAME, '주사' AS CATEGORY FROM OUTPATIENTNURSE_INJECTION oi JOIN MEDICINE m2 ON oi.MEDICINE_CODE = m2.MEDICINE_CODE LEFT JOIN COMMONCODE nc2 ON nc2.COMMONCODE_NUMBER = m2.MEDICINE_NAME AND nc2.COMMONCODE = 'M' WHERE EXTRACT(YEAR FROM oi.INJECTION_ORDER_TIME) = #{year}
UNION ALL
SELECT TREATMENT_ITEM_NAME AS ITEM_NAME, '물리치료' AS CATEGORY FROM PHYSICALTHERAPIST_RECORDS WHERE EXTRACT(YEAR FROM DATE_OF_TREATMENT) = #{year} ) GROUP BY ITEM_NAME, CATEGORY ORDER BY ITEM_COUNT DESC ) WHERE ROWNUM <= 5

SELECT '의약품' AS CATEGORY, COUNT(*) AS ORDER_COUNT FROM DOCTOR_PRESCRIPTION WHERE EXTRACT(YEAR FROM PRESCRIPTION_DATE) = #{year}
UNION ALL
SELECT '주사' AS CATEGORY, COUNT(*) AS ORDER_COUNT FROM OUTPATIENTNURSE_INJECTION WHERE EXTRACT(YEAR FROM INJECTION_ORDER_TIME) = #{year}
UNION ALL
SELECT '물리치료' AS CATEGORY, COUNT(*) AS ORDER_COUNT FROM PHYSICALTHERAPIST_RECORDS WHERE EXTRACT(YEAR FROM DATE_OF_TREATMENT) = #{year}
